// TH14 synthetic training aliases used by this card.
// Native type -> modern slot: 0..23 same number, 24..42 modern+1 (see transcribe/th14/bullet-types.md).
// Values are logical row bases, not the original TH14 type numbers.
const TH14_BALL2: int = 432;      // native type 5, radius 4.0, colors 0..15
const TH14_RING_BALL2: int = 464; // native type 7, radius 4.0, colors 0..15
const TH14_BIG_BALL: int = 640;   // native type 18, radius 8.5, colors 0..7

// th14_s1_w06 — TH14 v1.00b Stage 1 mid-stage wave.
// Entry: st01.ecl.txt::MainSub05 (934-950), source frame 0 = card frame 120.
// Closure: GirlD01/at/at2 (425-452, 454-515, 517-566), GirlA01c and the
// red/blue variants (127-156, 325-332, 586-593), MainSub05b/c (952-966, 968-982).
const TIME_LIMIT: int = 3324;
const OPENING_BUFFER: int = 120;

// Common one-shot ANGLE_ACCEL: type 8, a=30 frames, r=0 (speed untouched),
// s = per-frame angular velocity in BAM. Source samples RANDF2 per bullet at
// etExSet time; w is passed per bullet and sampled at the same call site.
xformdef D01_TURN30(w: int) {
    @30 set_ang_vel(w as angle);
    set_ang_vel(0 as angle);
}

