// st01.ecl.txt:425-452 GirlD01.
// Mirror is per-entity (moveSetMirror when FINAL_X>0); only movement uses it here.
async sub girl_d01() {
    set_invuln(65535);
    set_hurtbox(16fx); // setHurtbox(32,32) circle branch: first value * 0.5
    set_hitbox(12fx);  // setHitbox(24,24) circle branch: first value * 0.5
    var drift: int = 4096; // 22.5deg
    if $self_x > 0fx { drift = 28672; } // mirrored: pi - 22.5deg
    move_vel(0, 90deg, 3fx, EASE_LINEAR);
    move_vel(80, 90deg, 0fx, EASE_QUAD_IN); // moveVelTime(80,1,90deg,0)
    spawn d01_at();
    spawn d01_at2();
    wait(80);
    move_vel(0, drift as angle, 0fx, EASE_LINEAR);
    move_speed(120, 0.6fx, EASE_QUAD_IN); // moveSpeedTime(120,1,0.6f)
    wait(60);
    loop { wait(1000); }
}

// st01.ecl.txt:454-515 GirlD01_at.
// Per wave: one fan of A bullets fired in the same frame, then two centre shots
// 3 frames apart; A shrinks by 2 each of the 4 sub-waves.
async sub d01_at() {
    wait(60);
    var rounds: int = 2;
    var base_speed: fx = 1.1fx;
    var fan: int = 9;
    var pause: int = 180;
    var rk: int = global(GVAR_RANK);
    if rk > 0 { rounds = 4; }
    if rk == 2 { base_speed = 1.5fx; fan = 12; pause = 130; }
    if rk == 3 { base_speed = 2.1fx; fan = 15; pause = 90; }
    for round in 0..rounds {
        var b: fx = base_speed;
        var a: int = fan;
        for f in 0..4 {
            var spd: fx = b;
            b = b + 0.07fx;
            var d: int = 16384 - 182 * a; // C - (2deg*A)/2, BAM
            var g: int = a;
            for i in 0..g {
                var ang: int = d;
                d = d + 364; // +2 deg
                var r: int = rand(65536) - 32768;
                var w: int = r * 9 / 32768; // RANDF2 * 0.05 deg/frame in BAM
                // ANIM (type 2, a=1) birth stage is omitted but its retreat
                // offset position -= 4*velocity is kept.
                var bx: fx = $self_x - 4fx * spd * cos(ang as angle);
                var by: fx = $self_y - 4fx * spd * sin(ang as angle);
                _ = fire(TH14_BALL2, 9, bx, by, spd, ang as angle, D01_TURN30(w), none);
            }
            a = a - 2;
            wait(3);
            for h in 0..2 {
                var spd2: fx = b;
                b = b + 0.07fx;
                var r2: int = rand(65536) - 32768;
                var w2: int = r2 * 18 / 32768; // RANDF2 * 0.1 deg/frame in BAM
                var bx2: fx = $self_x - 4fx * spd2 * cos(90deg);
                var by2: fx = $self_y - 4fx * spd2 * sin(90deg);
                _ = fire(TH14_BALL2, 9, bx2, by2, spd2, 90deg, D01_TURN30(w2), none);
                wait(3);
            }
        }
        wait(pause);
    }
}

// st01.ecl.txt:517-566 GirlD01_at2. Single big shot per 3-frame tick, speed
// grows 0.07 per shot; BRIGHT (type 0x100000) is presentation only.
async sub d01_at2() {
    wait(60);
    var rounds: int = 2;
    var base_speed: fx = 1.1fx;
    var pause: int = 180;
    var rk: int = global(GVAR_RANK);
    if rk > 0 { rounds = 4; }
    if rk == 2 { base_speed = 1.5fx; pause = 130; }
    if rk == 3 { base_speed = 2.1fx; pause = 90; }
    for round in 0..rounds {
        var b: fx = base_speed;
        for e in 0..4 {
            var spd: fx = b;
            b = b + 0.07fx;
            var bx: fx = $self_x - 4fx * spd * cos(90deg);
            var by: fx = $self_y - 4fx * spd * sin(90deg);
            _ = fire(TH14_BIG_BALL, 3, bx, by, spd, 90deg, none, none);
            wait(3);
            for h in 0..2 {
                b = b + 0.07fx;
                wait(3);
            }
        }
        wait(pause);
    }
}

// st01.ecl.txt:127-156 GirlA01c (also GirlBlueA01c 325-332 / GirlRedA01c 586-593).
// setDeath("DeadAttack1") is Lunatic-only and needs a player kill; the invincible
// no-DPS shell never reaches it (see report.md).
async sub girl_a01c() {
    set_invuln(65535);
    set_hurtbox(12fx); // setHurtbox(24,24) -> 12
    set_hitbox(8fx);   // setHitbox(16,16) -> 8
    var a0: int = 0;
    var step: int = 182; // +1 deg/frame
    if $self_x > 0fx {
        a0 = 32768;
        step = -182;
    }
    move_vel(0, a0 as angle, 4fx, EASE_LINEAR);
    move_speed(60, 2.4fx, EASE_LINEAR); // moveSpeedTime(60,0,2.4f)
    wait(60);
    if global(GVAR_RANK) > 0 { spawn girl_a01_shots(); }
    // moveAngleTime(160,7,1deg) + moveSpeedTime(100,1,1.4f): the target velocity
    // layer keeps one easing at a time, so step both explicitly per source frame.
    for k in 1..161 {
        var u: fx = (k as fx) / 100fx;
        if u > 1fx { u = 1fx; }
        var sp: fx = 2.4fx - 1fx * u * u;
        move_vel(0, (a0 + k * step) as angle, sp, EASE_LINEAR);
        wait(1);
    }
    loop { wait(1000); }
}

// st01.ecl.txt:34-80 GirlA01_at. Aimed single bullets, count/speed/period by rank.
// Easy and Normal do not spawn this sub (source !NHL on the async call).
async sub girl_a01_shots() {
    var rk: int = global(GVAR_RANK);
    var rmax: int = 300;
    if rk >= 2 { rmax = 60; }
    wait(rand(rmax));
    var spd: fx = 1.2fx;
    var count: int = 1;
    var interval: int = 30;
    if rk == 2 { spd = 2.4fx; count = 5; interval = 60; }
    if rk == 3 { spd = 4.0fx; count = 10; interval = 60; }
    for i in 0..count {
        var ang: angle = aim_player();
        var bx: fx = $self_x - 4fx * spd * cos(ang);
        var by: fx = $self_y - 4fx * spd * sin(ang);
        _ = fire(TH14_BALL2, 6, bx, by, spd, ang, none, none);
        wait(interval);
    }
}

